"""Explain IRQ state restoration and RT local-lock variants."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1409': ('방의 알림 소리를 잠시 끈 뒤 원래 상태로 돌리려면, 처음 켜져 있었는지 꺼져 있었는지를 기억해야 합니다. 무조건 켜는 것과 원래대로 돌리는 것은 다릅니다.', '일반 구성에서 IRQ 끄기·켜기와 상태 저장·복구의 차이를 배웁니다.', '처음 IRQ 켜짐 → 저장하고 끔 → 복구하면 켜짐, 처음 꺼짐 → 저장하고 끔 → 복구해도 꺼짐이라는 두 줄을 쓰세요.', ['이 수업은 PREEMPT_RT가 꺼진 구성입니다. IRQ는 하드웨어 인터럽트 요청입니다. local_irq_disable은 현재 CPU의 해당 인터럽트 수신을 막는 제어이며 다른 CPU를 모두 멈추는 명령은 아닙니다.', '__local_lock_irq는 먼저 local_irq_disable을 하고 현재 CPU의 잠금 획득 기록으로 연결합니다. 대응 __local_unlock_irq는 기록 해제 뒤 local_irq_enable로 인터럽트를 켭니다. 이전 상태를 별도 변수에 저장하지 않습니다.', '__local_lock_irqsave는 local_irq_save(flags)로 기존 인터럽트 상태를 flags에 저장하면서 끕니다. flags는 나중에 복원할 상태를 담는 변수입니다. 단순한 잠금 성공 여부가 아닙니다.', '__local_unlock_irqrestore는 기록 해제 뒤 local_irq_restore(flags)를 호출합니다. 처음 켜져 있었다면 켜고, 처음 꺼져 있었다면 꺼진 상태로 돌립니다. restore라는 말은 언제나 켜라는 뜻이 아닙니다.', '바깥 코드가 이미 인터럽트를 껐는데 안쪽 함수가 끝날 때 무조건 켜면 바깥의 보호 조건을 깨뜨릴 수 있습니다. save와 restore를 짝지으면 안쪽 사용이 끝나도 바깥의 꺼진 상태를 유지할 수 있습니다.', '중첩 사용에서는 각 호출에 맞는 flags를 보관하고 올바른 짝으로 복구해야 합니다. 다른 호출의 값을 섞거나 덮어쓰면 원래 상태를 잃습니다. 인터럽트가 꺼진 구간의 잠들기 금지 같은 실행 조건도 지켜야 합니다.'], [('처음 IRQ가 꺼진 상태에서 irqsave와 대응 irqrestore를 하면 어떻게 될까요?', ['언제나 켜져요', '다시 꺼진 상태로 돌아가요'], 'save가 꺼져 있었다는 정보를 보관하고 restore가 그 상태를 복원합니다. 안쪽 처리가 바깥에서 끈 인터럽트를 임의로 켜면 안 됩니다.'), ('일반 구성의 unlock_irq와 irqrestore는 언제나 같은 효과일까요?', ['아니요. 켜기와 이전 상태 복구는 달라요', '네. 언제나 똑같은 상태를 만들어요'], 'unlock_irq는 enable이고 irqrestore는 저장한 상태를 복원합니다. 처음 꺼져 있던 경우 결과 차이가 드러납니다.')]), 'os1410': ('담당자가 잠시 일을 멈출 수는 있어도 다른 교실로 옮기지는 못하게 합니다. 공책의 잠금은 지금 교실에 있는 것을 사용하고 같은 곳에서 풀어야 합니다.', 'RT의 CPU 이동 금지와 선점 금지를 구별합니다.', 'CPU 2에서 이동 금지 → CPU 2 잠금 획득 → 자료 사용 → CPU 2 잠금 해제 → 이동 금지 복구 순서로 그리세요.', ['PREEMPT_RT는 실시간 응답을 위한 커널 구성입니다. 이 구성에서 local_lock_t는 spinlock_t로 정의됩니다. 일반 구성의 디버그 전용 구조체와 같은 구현이라고 생각하면 안 됩니다.', 'RT의 __local_lock은 먼저 migrate_disable을 호출합니다. migration은 실행 중인 작업이 다른 CPU로 이동하는 것입니다. CPU별 자료를 다루는 동안 어느 CPU의 자료를 사용하는지가 바뀌지 않게 합니다.', '그다음 spin_lock(this_cpu_ptr(lock))으로 현재 CPU의 잠금을 얻습니다. this_cpu_ptr는 CPU별 잠금 가운데 지금 CPU에 해당하는 것을 고릅니다. 이동 제어와 실제 CPU별 잠금이 함께 사용됩니다.', '원문은 이 보호 구간이 선점 가능한 상태를 유지한다고 설명합니다. 선점은 잠시 다른 작업이 실행되도록 차례를 바꾸는 것이고, migration은 다른 CPU로 옮기는 것입니다. 일을 잠시 멈추는 것과 다른 교실로 옮기는 것은 다른 제어입니다.', '해제에서는 먼저 현재 CPU의 spin_unlock을 실행한 다음 migrate_enable로 이동 금지를 되돌립니다. 이동을 먼저 허용하면 CPU별 획득과 해제의 연결을 유지하기 어려우므로 순서를 함께 읽어야 합니다.', 'RT에서 spinlock이라는 이름이 있다고 non-RT와 똑같이 선점을 금지한다고 외우면 안 됩니다. 그렇다고 보호 구간에서 아무 잠드는 함수나 사용해도 된다는 뜻도 아닙니다. 실제 RT 잠금 및 호출 문맥 규칙에 맞춰 사용하고 다른 CPU의 자료까지 자동 보호한다고 가정하지 마세요.'], [('RT 기본 local_lock이 먼저 하는 일은 무엇일까요?', ['언제나 preempt_disable이에요', 'migrate_disable이에요'], 'RT 매크로는 CPU 이동부터 막고 현재 CPU의 spinlock을 얻습니다. 일반 구성의 선점 금지와 다른 경로입니다.'), ('RT 해제에서 CPU 이동을 허용하는 것은 spin_unlock보다 먼저일까요?', ['아니요. 잠금을 푼 다음이에요', '네. 잠금을 풀기 전에 항상 이동부터 허용해요'], '원문 순서는 spin_unlock 다음 migrate_enable입니다. CPU별 잠금의 획득과 해제를 마친 뒤 이동 제어를 되돌립니다.')]), 'os1411': ('같은 이름의 버튼도 기계 종류에 따라 안쪽 연결이 다를 수 있습니다. RT에서 irqsave라는 이름만 보고 실제 인터럽트 상태를 저장한다고 단정하지 마세요.', 'RT IRQ 변형의 flags 처리와 일반 구성의 차이를 이해합니다.', 'RT: flags 타입 확인 → flags=0 → 기본 local_lock. 해제: 기본 local_unlock이라고 쓰세요. 일반 구성의 local_irq_save/restore와 별도 줄로 비교하세요.', ['PREEMPT_RT에서 __local_lock_irq는 기본 __local_lock으로 연결됩니다. 별도의 local_irq_disable을 추가하지 않습니다. 기본 경로는 CPU 이동을 막고 현재 CPU의 잠금을 얻는 구조입니다.', 'RT의 __local_lock_irqsave는 먼저 typecheck(unsigned long, flags)를 수행합니다. typecheck는 C 변수의 종류가 맞는지 검사하기 위한 코드입니다. flags에 현재 하드웨어 상태를 읽어 넣는 동작이 아닙니다.', '다음 줄은 flags=0입니다. 이 0은 실제 IRQ 상태를 읽은 결과가 아니라 코드가 정해 넣은 값입니다. 따라서 flags가 0이라고 이전 인터럽트가 켜졌는지 꺼졌는지 추론할 수 없습니다.', '그 뒤 __local_lock을 호출합니다. 같은 공개 인자 모양을 유지하면서 RT에 맞는 CPU별 잠금 구현으로 이어집니다. non-RT의 local_irq_save와 동일한 내부 동작은 아닙니다.', 'RT __local_unlock_irqrestore는 __local_unlock에 연결됩니다. 이 매크로는 전달된 flags를 하드웨어 복원에 사용하지 않습니다. 실제로는 현재 CPU 잠금을 풀고 migration 제어를 되돌리는 기본 경로입니다.', '그러므로 IRQ 이름이 붙었다는 이유만으로 RT에서 hard IRQ가 꺼져 있다고 가정하면 안 됩니다. 같은 자료를 인터럽트에서도 만지는지와 RT의 실행 문맥 규칙을 확인해야 합니다. flags 타입과 올바른 획득·해제 짝도 지키세요.'], [('RT irqsave 매크로는 flags에 무엇을 대입할까요?', ['언제나 실제 이전 IRQ 상태예요', '코드에 적힌 0이에요'], 'typecheck 다음 줄이 flags=0입니다. 상태를 읽는 local_irq_save 호출이 아니므로 일반 구성과 구별해야 합니다.'), ('RT irqrestore는 flags로 하드웨어 IRQ 상태를 복원할까요?', ['아니요. 기본 local_unlock으로 연결돼요', '네. 언제나 local_irq_restore를 실행해요'], 'RT 정의는 __local_unlock(lock)입니다. flags를 실제 복원에 사용하는 non-RT 정의와 다른 연결입니다.')]), 'os1412': ('이미 정해진 작업 구역 안에 들어온 사람만 쓰는 도구가 있습니다. 입장 여부를 확인하는 표시는 사람을 그 구역으로 자동 이동시키지 않습니다.', 'nested BH가 요구하는 softirq 문맥과 추가하지 않는 제어를 이해합니다.', '일반 구성: softirq 조건 확인 → 분석 획득. RT: softirq 함수 조건 확인 → 현재 CPU spinlock. 두 줄에 새 migrate_disable 호출은 없다고 표시하세요.', ['BH는 bottom half라는 말에서 온 이름이며 여기서는 softirq 처리 문맥과 관련됩니다. softirq는 인터럽트와 연결된 후속 작업 등을 처리하는 커널 실행 방식입니다. nested BH 변형은 이미 필요한 실행 조건 안에 있다는 전제로 사용합니다.', 'non-RT __local_lock_nested_bh는 먼저 lockdep_assert_in_softirq를 호출합니다. 분석 도구에 softirq 조건을 확인하도록 하는 표시입니다. 이 표시가 일반 코드를 자동으로 softirq 문맥으로 바꾸는 것은 아닙니다.', '이어서 현재 CPU의 local_lock_acquire로 분석 기록을 합니다. 대응 해제는 local_lock_release입니다. 이 매크로 자체에는 새로운 preempt_disable이나 local_irq_disable이 없습니다. 필요한 바깥 문맥 조건을 생략해도 된다는 뜻이 아닙니다.', 'RT에서는 lockdep_assert_in_softirq_func 뒤 spin_lock(this_cpu_ptr(lock))을 호출합니다. 해제는 현재 CPU의 spin_unlock입니다. 단순 분석 기록 대신 RT에 필요한 잠금 경로를 사용합니다.', 'RT의 기본 local_lock과 달리 이 nested 매크로에는 migrate_disable이 직접 없습니다. 따라서 기본 함수의 모든 준비 단계를 이곳도 추가한다고 가정하면 안 됩니다. 이미 갖춰진 softirq 문맥의 조건과 실제 호출 경로를 함께 확인해야 합니다.', 'nested라는 이름도 같은 잠금을 마음대로 반복 획득해도 된다는 허가가 아닙니다. 일반 작업 문맥에서 보호 대용으로 쓰지 말고, 문맥 조건과 대응 해제를 지키세요. 분석용 assert는 잘못된 사용을 알려 주는 역할이며 실행 조건을 만들어 주는 보호 명령과 다릅니다.'], [('non-RT nested BH가 처음 확인하는 문맥은 무엇일까요?', ['언제나 일반 사용자 작업 문맥이에요', 'softirq 문맥이에요'], '첫 줄은 lockdep_assert_in_softirq입니다. 필요한 문맥을 확인하며 그 문맥을 새로 만드는 호출은 아닙니다.'), ('RT nested BH 매크로도 기본 RT local_lock처럼 migrate_disable을 직접 추가할까요?', ['아니요. 해당 매크로에는 그 호출이 없어요', '네. 언제나 이동 금지 깊이를 하나 늘려요'], '원문은 assert와 현재 CPU의 spin_lock으로 구성됩니다. 바깥 문맥이 제공하는 조건과 매크로가 직접 수행하는 동작을 구별해야 합니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_348.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
